import type { VercelRequest, VercelResponse } from '@vercel/node';

const images = {
  '1': '',
  '2': '',
  '3': '',
  '4': '',
  '5': '',
  '6': ''
} as const;

type SectionKey = keyof typeof images;

export default function handler(request: VercelRequest, response: VercelResponse) {
  const rawSection = Array.isArray(request.query['section'])
    ? request.query['section'][0]
    : request.query['section'];
  const section = rawSection as SectionKey | undefined;
  const encodedImage = section ? images[section] : undefined;

  if (!encodedImage) {
    response.setHeader('Cache-Control', 'no-store');
    return response.status(404).json({ error: 'Image not found.' });
  }

  response.setHeader('Content-Type', 'image/jpeg');
  response.setHeader('Content-Disposition', `inline; filename="brains-heist-school-section-${section}.jpg"`);
  response.setHeader('Cache-Control', 'public, max-age=31536000, s-maxage=31536000, immutable');
  return response.status(200).send(Buffer.from(encodedImage, 'base64'));
}
